'use strict';

var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var filledarrayBy = require( '@stdlib/array/filled-by' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var logEach = require( '@stdlib/console/log-each' );
var ztpsv = require( './../lib' );

function rand() {
	return new Complex128( discreteUniform( 0, 10 ), discreteUniform( -5, 5 ) );
}

var N = 3;

var x = filledarrayBy( N, 'complex128', rand );
var AP = filledarrayBy( (N*(N+1)/2), 'complex128', rand );

ztpsv( 'column-major', 'lower', 'no-transpose', 'unit', N, AP, x, 1 );

// Print the results:
logEach( '%s', x );

ztpsv.ndarray( 'row-major', 'upper', 'transpose', 'non-unit', N, AP, 1, 0, x, 1, 0 );

// Print the results:
logEach( '%s', x );
